rewrite:
def cartesian_product(a, b):
    for i in a:
        for j in b:
            yield (i, j)


def cartesian_product_of_shape(dimentions, result=None):
    if result is None:
        result = [[]]

    for dim in dimentions:
        new_result = []
        for item in result:
            for i in range(dim):
                new_result.append(item + [i])
        result = new_result

    return result
